{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "A tocotrienol-rich fraction of palm oil, a lipophilic isoprenoid with a polar chromanol head, showed poor oral bioavailability in humans, supporting low absorption for structurally related lipophilic isoprenoid quinones.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Lycopene, a long-chain lipophilic isoprenoid, showed only about 1.2% systemic availability after an oral dose dispersed in oil in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lycopene from tomato paste showed only 0.17% of the dose detected in circulation, indicating very low systemic availability for a highly lipophilic long-chain isoprenoid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "In a 13C-lycopene study, all-trans lycopene bioavailability was estimated at 23.2% ± 8%, suggesting that some long-chain isoprenoids can be substantially absorbed when measured by compartmental modeling.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene, a less-conjugated carotenoid, showed an absolute bioavailability of 58.5% ± 18.9% in humans, indicating that some highly lipophilic isoprenoids can be well absorbed.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a long-chain polyprenyl ubiquinone with very low aqueous solubility and high lipophilicity. The most transferable experimental evidence—tocotrienols and lycopene—indicates poor oral bioavailability for this class, while the high values for phytoene and labeled lycopene are less transferable because of differences in head-group polarity, conjugation, and measurement method. Overall, F >= 20% is not supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ubiquinone/CoQ-type molecules in the provided records.",
    "No human absolute bioavailability data for the exact query molecule.",
    "The high phytoene and labeled-lycopene estimates rely on compartmental modeling rather than classic AUC-based absolute bioavailability, limiting comparability."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tocotrienol"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C04", "C07"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "lycopene"
    },
    {
      "applicability": "low",
      "card_ids": ["C13"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "lycopene"
    },
    {
      "applicability": "low",
      "card_ids": ["C02"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "phytoene"
    }
  ],
  "revision_action": "initial"
}

